(()=>{const t=window.BarfordMemberFlow,p=window.BarfordSupabase,n=document.getElementById("memberPayments"),s=new URLSearchParams(location.search).get("event");if(!t||!n)return;if(s){const r=document.getElementById("paymentBack");r.href=t.eventUrl(s),r.textContent="\u2190 Back to my event"}async function u(){try{const r=await t.request(p.auth.getSession());if(!r.session){n.innerHTML=`<article class="simple-card"><h2>Sign in to see your payments</h2><a class="button button-primary" href="${t.loginUrl(location.href)}">Sign in</a></article>`;return}const y=p.from("rsvps").select("event_id,status,payment_status,is_course_member").eq("member_id",r.session.user.id),c=await t.request(s?y.eq("event_id",s):y),h=s?[s]:c.filter(e=>e.status==="playing"||["paid","refunded","waived"].includes(e.payment_status)).map(e=>e.event_id);if(!h.length){n.innerHTML='<article class="simple-card"><h2>No event payments to show</h2><p>Your payments will appear here when you book an event.</p><a class="button button-primary" href="events.html">View events</a></article>';return}const i=await t.request(p.from("events").select("*").in("id",h).order("event_date"));if(!i.length){n.innerHTML='<article class="simple-card"><h2>Event not found</h2><a class="button button-outline" href="payments.html">View all my payments</a></article>';return}const o=t.paymentSummary(i,c),b=i.filter(e=>t.payment(e,c.find(a=>a.event_id===e.id)).due),l=i.filter(e=>!b.includes(e)),m=e=>{const a=c.find(f=>f.event_id===e.id),d=t.payment(e,a);return`<article class="simple-card payment-receipt"><p class="eyebrow">${t.esc(t.date(e.event_date))}</p><h2>${t.esc(e.name)}</h2><p>${t.esc(t.priceLabel(a))}</p><p class="simple-payment-state"><strong>${t.esc(d.label)}</strong></p>${d.due?"<p>Online payments are coming soon. Pay now opens a demonstration; no money is taken. Use Get payment instructions to arrange a real payment.</p>":e.status==="cancelled"&&a?.payment_status==="paid"?"<p>Contact the committee to check your refund.</p>":a?.status==="reserve"?"<p>No payment is needed while you wait for a place.</p>":""}${d.due?`<button type="button" class="button button-primary full-button" data-pay-now="${t.esc(e.id)}">Pay now \xB7 ${t.esc(t.money(t.eventPrice(e,a)))}</button><button type="button" class="button button-outline full-button" data-payment-help="${t.esc(e.id)}">Get payment instructions</button><details class="simple-details"><summary>Already sent your payment?</summary><p>It has not been confirmed yet. Ask the committee to check before paying again.</p><button class="button button-outline" data-payment-check="${t.esc(e.id)}">Ask for confirmation</button></details>`:""}${a?.status==="playing"&&e.status==="scheduled"?`<a class="button button-outline full-button" href="${t.eventUrl(e.id)}#my-group">View my tee group \u2192</a><p>Your tee time and group appear there when announced.</p>`:""}<a class="simple-back" href="${t.eventUrl(e.id)}">Back to this event</a></article>`};n.innerHTML=`<section class="simple-card"><p class="eyebrow">${s?"This event":"My payments"}</p><h2>\xA3${(o.pence/100).toFixed(2)} outstanding</h2><p>${o.count?`${o.count} event${o.count===1?"":"s"} to pay.`:"No confirmed event fees outstanding."}${o.unpriced?` ${o.unpriced} booking${o.unpriced===1?" is":"s are"} awaiting a price.`:""}</p><button class="button button-outline" id="refreshPaymentStatus" type="button">Check payment status</button>${s?'<a class="simple-back" href="payments.html">All my payments</a>':""}</section>`+b.map(m).join("")+(l.length?s?l.map(m).join(""):`<details class="simple-card simple-details"><summary>Other bookings and payment history (${l.length})</summary><div class="simple-detail-content">${l.map(m).join("")}</div></details>`:""),n.querySelector("#refreshPaymentStatus").onclick=u,n.querySelectorAll("[data-pay-now]").forEach(e=>e.onclick=()=>window.BarfordPayments.pay(i.find(a=>a.id===e.dataset.payNow),c.find(a=>a.event_id===e.dataset.payNow),e)),n.querySelectorAll("[data-payment-help],[data-payment-check]").forEach(e=>e.onclick=()=>t.contact(i.find(a=>a.id===(e.dataset.paymentHelp||e.dataset.paymentCheck)),e.dataset.paymentCheck?"check a payment I have already made":"get the payment details"))}catch{n.innerHTML='<article class="simple-card"><h2>Payments could not be checked</h2><p>Please try again to see the latest payment status.</p><button class="button button-primary" id="retryPayments">Try again</button></article>',n.querySelector("#retryPayments").onclick=u}}u()})();
